        <button onClick={()=>{setTab('Investments');setOpen(false);}} className='flex min-h-14 items-center justify-center gap-2 rounded-full border border-[#6B2737] bg-white px-5 py-4 font-extrabold text-[#6B2737] transition hover:bg-[#F5EDEF]'><TrendingUp size={19}/> Buy Plan</button>
