function AuthPage({onSuccess,onHome,initialMode}:{onSuccess:()=>Promise<void>;onHome:()=>void;initialMode:'signin'|'signup'}) {
  const [mode,setMode]=useState<'signin'|'signup'>(initialMode);
  const [showPassword,setShowPassword]=useState(false);
  const [remember,setRemember]=useState(true);
  const [loading,setLoading]=useState(false);
  const [message,setMessage]=useState('');
  const [error,setError]=useState('');
  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [username,setUsername]=useState('');
  const [fullName,setFullName]=useState('');
  const [phone,setPhone]=useState('');
  const [country,setCountry]=useState('');
  const [referralCode,setReferralCode]=useState(()=>{try{return new URLSearchParams(window.location.search).get('ref')||localStorage.getItem('pledge_ref_code')||'';}catch{return '';}});
  const [confirmPassword,setConfirmPassword]=useState('');
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setMessage('');
    if(mode==='signup'&&password!==confirmPassword){setError('Passwords do not match.');return;}
    if(mode==='signup'&&password.length<8){setError('Use a password with at least 8 characters.');return;}
    setLoading(true);
    try {
      if(mode==='signin'){await auth.signIn(email,password);await onSuccess();}
      else {
        if(referralCode)try{localStorage.setItem('pledge_ref_code',referralCode.trim().toUpperCase());}catch{} const result=await auth.signUp({email,password,username,fullName,phone,country,referralCode});
        if(result.session){if(referralCode)try{localStorage.setItem('pledge_ref_code',referralCode.trim().toUpperCase());}catch{} await onSuccess();}
        else {setMessage('Account created. Check your email for the confirmation link, then return here to sign in.');setMode('signin');setPassword('');setConfirmPassword('');}
      }
    } catch(e:any){setError(e?.message||'Unable to continue. Please check your details and try again.');}
    finally{setLoading(false);}
  };
  const forgot=async()=>{setError('');setMessage('');if(!email.trim()){setError('Enter your email address first.');return;}setLoading(true);try{await auth.resetPassword(email);setMessage('Password reset link sent if this email is registered. Check your inbox.');}catch(e:any){setError(e?.message||'Unable to send a reset email.');}finally{setLoading(false);}};
  const input="w-full rounded-xl border border-slate-700 bg-[#18304a] px-4 py-3.5 text-sm text-white placeholder:text-slate-400 outline-none transition focus:border-indigo-400 focus:ring-2 focus:ring-indigo-400/20";
  const label="mb-2 block text-sm font-medium text-slate-300";
  return <div className="min-h-screen bg-[#071426] px-4 py-5 text-white sm:py-10">
    <div className="mx-auto flex w-full max-w-xl items-center justify-between gap-3 rounded-2xl border border-slate-700/70 bg-[#10233a] p-1.5"><button type="button" onClick={onHome} className="rounded-xl px-4 py-3 text-sm font-bold text-slate-300">← Home</button>
      <button type="button" onClick={()=>{setMode(mode==='signin'?'signup':'signin');setError('');setMessage('');}} className="w-full rounded-xl bg-[#18304a] px-4 py-3 text-sm font-bold text-white">{mode==='signin'?'Open Account':'Sign In'}</button>
    </div>
    <main className="mx-auto mt-8 w-full max-w-xl rounded-[28px] border border-slate-700/80 bg-[#10213a] p-5 shadow-2xl shadow-black/20 sm:mt-12 sm:p-9">
      <div className="flex items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-indigo-600 text-lg font-black tracking-tight">PI</div><div><div className="text-xl font-black tracking-tight sm:text-2xl">PLEDGE INVEST</div><div className="mt-1 flex items-center gap-2 text-xs text-slate-400"><span className="h-2 w-2 rounded-full bg-indigo-400"/> Advanced Investment Platform</div></div></div>
        <span className="rounded-full border border-slate-700 px-3 py-2 text-xs font-bold text-slate-300">EN</span>
      </div>
      <h1 className="mt-9 text-3xl font-black tracking-tight">{mode==='signin'?'Welcome Back':'Create Account'}</h1>
      <p className="mt-2 text-sm text-slate-400">{mode==='signin'?'Sign in to continue investing':'Start your investment journey today'}</p>
      <form onSubmit={submit} className="mt-7 space-y-5">
        {mode==='signup'&&<><div><label className={label}>Username</label><input className={input} autoComplete="username" required value={username} onChange={e=>setUsername(e.target.value)} placeholder="yourusername"/></div><div><label className={label}>Full name</label><input className={input} autoComplete="name" required value={fullName} onChange={e=>setFullName(e.target.value)} placeholder="Your full name"/></div></>}
        <div><label className={label}>Email</label><input className={input} type="email" autoComplete="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></div>
        {mode==='signup'&&<><div><label className={label}>Phone</label><input className={input} type="tel" autoComplete="tel" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+234 ..."/></div><div><label className={label}>Country</label><select className={input} required value={country} onChange={e=>setCountry(e.target.value)}><option value="">Select country</option>{['Nigeria','Ghana','Kenya','South Africa','United States','United Kingdom','Canada','India','Other'].map(x=><option key={x} value={x}>{x}</option>)}</select></div><div><label className={label}>Referral username (optional)</label><input className={input} value={referralCode} onChange={e=>setReferralCode(e.target.value)} placeholder="REF123"/></div></>}
        <div><label className={label}>Password</label><div className="relative"><input className={input+" pr-14"} type={showPassword?'text':'password'} autoComplete={mode==='signin'?'current-password':'new-password'} required minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/><button type="button" onClick={()=>setShowPassword(v=>!v)} className="absolute inset-y-0 right-0 px-4 text-sm font-semibold text-slate-400">{showPassword?'Hide':'Show'}</button></div></div>
        {mode==='signup'&&<div><label className={label}>Repeat Password</label><input className={input} type={showPassword?'text':'password'} autoComplete="new-password" required minLength={8} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="Repeat your password"/></div>}
        {mode==='signin'&&<div className="flex items-center justify-between gap-3 text-sm"><label className="flex items-center gap-2 text-slate-300"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)} className="h-4 w-4 accent-indigo-500"/> Remember me</label><button type="button" onClick={forgot} className="font-semibold text-indigo-400 hover:text-blue-300">Forgot Password?</button></div>}
        {error&&<div role="alert" className="rounded-xl border border-red-400/30 bg-red-500/10 p-3 text-sm text-red-200">{error}</div>}
        {message&&<div role="status" className="rounded-xl border border-indigo-400/30 bg-indigo-500/10 p-3 text-sm text-blue-200">{message}</div>}
        <button disabled={loading} className="w-full rounded-full bg-indigo-500 px-5 py-4 text-base font-extrabold text-[#05251f] shadow-lg shadow-indigo-950/20 transition hover:bg-indigo-400 disabled:cursor-wait disabled:opacity-60">{loading?'Please wait…':mode==='signin'?'Sign In':'Create Account'}</button>
      </form>
      <p className="mt-6 text-center text-sm text-slate-400">{mode==='signin'?'Not a Member yet?':'Already have an account?'} <button type="button" onClick={()=>{setMode(mode==='signin'?'signup':'signin');setError('');setMessage('');}} className="font-bold text-indigo-400 hover:text-blue-300">{mode==='signin'?'Sign Up':'Sign In'}</button></p>
      <div className="mt-8 rounded-2xl border border-slate-700/70 bg-gradient-to-br from-indigo-500/10 to-blue-500/5 p-5"><div className="inline-block rounded-md bg-indigo-500 px-2 py-1 text-xs font-black text-[#05251f]">PLEDGE INVEST</div><h2 className="mt-3 font-bold">Grow your wealth</h2><p className="mt-1 text-sm text-slate-400">Sign in to access your portfolio</p></div>
      <p className="mt-6 text-center text-xs leading-5 text-slate-500">By creating an account, you agree to our <span className="text-indigo-400">Terms</span>, <span className="text-indigo-400">Privacy</span> and <span className="text-indigo-400">Risk policies</span>.</p>
    </main>
    <p className="mx-auto mt-6 max-w-xl text-center text-xs text-slate-600">© 2026 Pledge Invest</p>
  </div>;
}

function Info({title,value,icon}:{title:string;value:string;icon:ReactNode}){return <div className='rounded-2xl border bg-white p-6 shadow-sm'><div className='flex items-center gap-3'><div className='rounded-xl bg-indigo-50 p-2 text-indigo-600'>{icon}</div><span className='text-sm font-semibold text-slate-500'>{title}</span></div><div className='mt-5 break-words text-xl font-black'>{value}</div></div>}
function Empty({title,text}:{title:string;text:string}){return <div className='rounded-2xl border border-dashed bg-slate-50 p-8 text-center'><div className='font-black'>{title}</div><div className='mt-2 text-sm text-slate-500'>{text}</div></div>}
function Doc({title,meta}:{title:string;meta:string}){return <div className='flex items-center gap-4 rounded-2xl border bg-white p-5 shadow-sm'><div className='rounded-xl bg-indigo-50 p-3 text-indigo-600'><FileText size={20}/></div><div><div className='font-bold'>{title}</div><div className='text-xs text-slate-500'>{meta}</div></div></div>}
